// ============================================================
// SCORING ENGINE: Multi-Factor Score Calculation (v3.0)
// ============================================================

const data = $json;
const extracted = data.extracted_data || {};

let score = 0;
const breakdown = {
  documents: 0,
  experience: 0,
  age: 0,
  communication: 0
};

// 1. Documents Score (0-25)
const docStatus = String(extracted.documents_status || '').toLowerCase();
if (docStatus === 'yes' || docStatus === 'complete' || docStatus === 'да' || docStatus === 'есть') {
  breakdown.documents = 25;
} else if (docStatus === 'partial' || docStatus === 'частично') {
  breakdown.documents = 15;
} else if (docStatus === 'processing' || docStatus === 'оформляю' || docStatus === 'в процессе') {
  breakdown.documents = 10;
} else if (docStatus === 'no' || docStatus === 'нет' || docStatus === 'missing') {
  breakdown.documents = 0;
} else {
  breakdown.documents = 5;
}
score += breakdown.documents;

// 2. Experience Score (0-25)
const expText = String(extracted.experience || '').toLowerCase();
const expMatch = expText.match(/(\d+)/);
const expYears = expMatch ? parseInt(expMatch[1]) : 0;

if (expYears >= 5) breakdown.experience = 25;
else if (expYears >= 3) breakdown.experience = 20;
else if (expYears >= 1) breakdown.experience = 15;
else if (expText.includes('есть') || expText.includes('работал')) breakdown.experience = 12;
else breakdown.experience = 5;
score += breakdown.experience;

// 3. Age Score (0-25)
const age = parseInt(extracted.age) || 0;
if (age > 0 && age <= 35) breakdown.age = 25;
else if (age > 35 && age <= 45) breakdown.age = 20;
else if (age > 45 && age <= 50) breakdown.age = 15;
else if (age > 50 && age <= 55) breakdown.age = 10;
else if (age > 55) breakdown.age = 5;
else breakdown.age = 10;
score += breakdown.age;

// 4. Communication Score (0-25)
breakdown.communication = 20;
score += breakdown.communication;

// Determine recommendation
let recommendation = 'manual_review';
let rejectionReason = null;

if (age > 55) {
  recommendation = 'auto_reject';
  rejectionReason = 'age';
} else if (docStatus === 'no' || docStatus === 'нет' || docStatus === 'missing') {
  recommendation = 'auto_reject';
  rejectionReason = 'documents';
} else if (docStatus === 'processing' || docStatus === 'оформляю') {
  recommendation = 'documents_pending';
} else if (score >= 70) {
  recommendation = 'auto_approve';
} else if (score >= 50) {
  recommendation = 'manual_review';
} else {
  recommendation = 'auto_reject';
  rejectionReason = 'low_score';
}

return {
  ...data,
  final_score: score,
  score_breakdown: breakdown,
  recommendation: recommendation,
  rejection_reason: rejectionReason
};

